import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"我的钱包 - 账户余额","description":"","frontmatter":{"title":"我的钱包 - 账户余额"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/wallet-balance.md","filePath":"ops-knowledge-base/presales-support/wallet-balance.md","lastUpdated":1788259091000}'),o={name:"ops-knowledge-base/presales-support/wallet-balance.md"};function n(s,a,i,d,h,p){return t(),l("div",null,[...a[0]||(a[0]=[r('<h2 id="一、功能概述" tabindex="-1">一、功能概述 <a class="header-anchor" href="#一、功能概述" aria-label="Permalink to &quot;一、功能概述&quot;">​</a></h2><p>平台财务管理模块支持账户充值、余额变动明细查询等功能，帮助用户清晰掌握账户资金流向与余额状态，便捷完成资金相关操作。</p><h2 id="二、账户余额与充值" tabindex="-1">二、账户余额与充值 <a class="header-anchor" href="#二、账户余额与充值" aria-label="Permalink to &quot;二、账户余额与充值&quot;">​</a></h2><h3 id="一-功能入口" tabindex="-1">（一）功能入口 <a class="header-anchor" href="#一-功能入口" aria-label="Permalink to &quot;（一）功能入口&quot;">​</a></h3><p>通过导航路径 <strong>客户中心 / 财务管理 / 我的钱包</strong> 进入 “账户余额” 界面。</p><h3 id="二-功能说明" tabindex="-1">（二）功能说明 <a class="header-anchor" href="#二-功能说明" aria-label="Permalink to &quot;（二）功能说明&quot;">​</a></h3><p>界面顶部展示当前<strong>账户余额</strong>，右侧提供 “充值” 按钮，点击可跳转至账户充值页面完成资金充值操作。</p><h2 id="三、账户充值" tabindex="-1">三、账户充值 <a class="header-anchor" href="#三、账户充值" aria-label="Permalink to &quot;三、账户充值&quot;">​</a></h2><h3 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h3><ul><li><strong>充值规则</strong>：最低充值金额 $1.00 USD，最高充值金额 $20000.00 USD，账户预存上限 $100000.00 USD。</li><li><strong>操作流程</strong>：在 “充值金额” 输入框填写符合规则的金额；在 “付款方式” 下拉框选择 BitPay、贝宝、支付宝 - 5 等方式；点击 “账户充值” 按钮完成操作。</li><li><strong>注意事项</strong>：账户余额不支持提现，充值前请确认金额与付款方式，避免误操作。</li></ul><h2 id="四、余额变动明细" tabindex="-1">四、余额变动明细 <a class="header-anchor" href="#四、余额变动明细" aria-label="Permalink to &quot;四、余额变动明细&quot;">​</a></h2><h3 id="功能说明-1" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明-1" aria-label="Permalink to &quot;功能说明&quot;">​</a></h3><ol><li><p><strong>查询筛选</strong></p><ul><li>支持通过 “开始日期”“结束日期”（含 “过去 7 天”“过去 30 天” 快捷选项）精准选择查询时间范围。</li><li>可通过 “筛选状态” 下拉框选择 “全部”“入账”“消费”，快速筛选对应类型的资金变动记录；选择后点击 “查询” 按钮即可获取目标明细。</li></ul></li><li><p><strong>明细展示</strong></p><p>交易列表包含以下信息：</p><ul><li><strong>交易时间</strong>：每笔资金变动的具体日期。</li><li><strong>余额使用明细</strong>：记录资金变动的原因（如 “Credit Applied to Invoice #XXX” 代表账单扣款、“Add Funds Invoice #XXX” 代表账户充值等）。</li><li><strong>金额</strong>：正数为资金入账（如充值、退款），负数为资金消费（如账单支付）。</li><li><strong>余额</strong>：每笔交易完成后的账户实时余额。</li></ul></li><li><p><strong>分页浏览</strong></p><p>界面底部支持分页查看更多交易记录，可通过 “上一页”“下一页” 按钮切换页码。</p></li></ol>',13)])])}const g=e(o,[["render",n]]);export{u as __pageData,g as default};
